# --- anchored in-place edits to prod settings.py + main.py (divergent files) ---
python3 - <<'PYEOF'
# settings.py: add shipment progression flags after shipment_webhook_secret
p='app/core/settings.py'
s=open(p).read()
anchor='    shipment_webhook_secret: str = os.environ.get("SHIPMENT_WEBHOOK_SECRET", "")\n'
assert anchor in s, 'settings anchor missing'
if 'shipment_progression_enabled' not in s:
    add=anchor+'''    # ECOMX-30: background shipment-tracking progression runner. When enabled a
    # timer advances in-flight ship-group shipments one honest step each cycle
    # (EasyPost poll when keyed; internal mock progression otherwise) so a
    # shipped order reaches delivered without an admin clicking simulate.
    shipment_progression_enabled: bool = os.environ.get("SHIPMENT_PROGRESSION_ENABLED", "false").lower() not in ("0", "false", "")
    shipment_progression_interval_seconds: int = int(os.environ.get("SHIPMENT_PROGRESSION_INTERVAL_SECONDS", "300"))
    shipment_progression_batch_size: int = int(os.environ.get("SHIPMENT_PROGRESSION_BATCH_SIZE", "200"))
'''
    s=s.replace(anchor,add,1)
    open(p,'w').write(s)
    print('settings.py patched')
else:
    print('settings.py already has flag (skip)')

# main.py: wire the progression startup task after the carrier polling task
p='app/main.py'
s=open(p).read()
anchor='    from app.services.carrier_tracking_poller import start_carrier_polling_task\n    app.add_event_handler("startup", start_carrier_polling_task)\n'
assert anchor in s, 'main anchor missing'
if 'start_shipment_progression_task' not in s:
    add=anchor+'''    from app.services.shipment_tracking_runner import start_shipment_progression_task  # ECOMX-30
    app.add_event_handler("startup", start_shipment_progression_task)
'''
    s=s.replace(anchor,add,1)
    open(p,'w').write(s)
    print('main.py patched')
else:
    print('main.py already wired (skip)')

import ast
for f in ('app/core/settings.py','app/main.py','app/services/carrier_tracking.py','app/services/shipment_tracking.py','app/services/shipment_tracking_runner.py','app/routers/shipment_tracking.py'):
    ast.parse(open(f).read())
print('ALL PARSE OK')
PYEOF
